const { chromium } = require('/home/lane/rblx/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/google-chrome',
    args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
  const page = await browser.newPage();
  page.on('console', (m) => console.log('[console]', m.type(), m.text()));
  page.on('pageerror', (e) => console.log('[pageerror]', e.message));
  page.on('requestfailed', (r) => console.log('[reqfail]', r.url(), r.failure().errorText));
  const resp = await page.goto('http://localhost:3001', { waitUntil: 'networkidle' });
  console.log('status:', resp.status());
  await page.waitForTimeout(2000);
  console.log('body snippet:', (await page.content()).slice(0, 600));
  await page.screenshot({ path: '/tmp/glint-shots/debug.png' });
  await browser.close();
})();
EOF
node glint-debug.js
